    for (int number = 1; number <= 8; number++) {
        if (number % 2 == 0) {
            printf("%d\n", number);
        }
    }
    return 0;
}

#include <stdio.h>

int sum(const int values[], size_t length) {
    int total = 0;
    for (size_t i = 0; i < length; i++) {
        total += values[i];
    }
    return total;
}

int main(void) {
    int values[] = {2, 4, 6};
    printf("%d\n", sum(values, sizeof values / sizeof values[0]));
    return 0;
}

#include <stdio.h>

struct Counter {
    int value;
};

void increment(struct Counter *counter) {
    counter->value += 1;
}

int main(void) {
    struct Counter tally = {0};
    increment(&tally);
    printf("%d\n", tally.value);
    return 0;
}

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    const char text[] = "42";
    char *end;
    errno = 0;
    long value = strtol(text, &end, 10);
    if (end == text || *end != '\0' || errno == ERANGE) {
        return 1;
    }
    printf("%zu characters, value %ld\n", strlen(text), value);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t length = 4;
    int *scores = calloc(length, sizeof *scores);
    if (scores == NULL) return 1;
    scores[0] = 8;
    printf("%d\n", scores[0]);
    free(scores);
    return 0;
}

#include <stdio.h>

int main(void) {
    FILE *stream = tmpfile();
    if (stream == NULL) return 1;
    if (fputs("first line\n", stream) == EOF) {
        fclose(stream);
        return 1;
    }
    rewind(stream);
    char line[32];
    if (fgets(line, sizeof line, stream)) printf("%s", line);
    int failed = ferror(stream);
    return fclose(stream) == EOF || failed;
}
